/**
 * Query helper functions for Room Dataset 10
 */

/**
 * Retrieves all room records in dataset 10
 * @returns {Array<Object>} List of room records
 */
function getAllRooms() {
  return staticRoomMaster10;
}

/**
 * Finds room record by roomId
 * @param {string} roomId
 * @returns {Object|null} Matching room record or null
 */
function findRoomById(roomId) {
  if (!roomId || typeof roomId !== 'string') {
    return null;
  }
  return staticRoomMaster10.find((room) => room.roomId.toUpperCase() === roomId.trim().toUpperCase()) || null;
}

/**
 * Filters rooms by block name substring or full match
 * @param {string} blockName
 * @returns {Array<Object>} List of matched rooms
 */
function filterRoomsByBlock(blockName) {
  if (!blockName || typeof blockName !== 'string') {
    return [];
  }
  const query = blockName.trim().toLowerCase();
  return staticRoomMaster10.filter((room) => room.blockName.toLowerCase().includes(query));
}

/**
 * Filters rooms by floor number
 * @param {number} floorNumber
 * @returns {Array<Object>} Filtered rooms on floor
 */
function filterRoomsByFloor(floorNumber) {
  if (typeof floorNumber !== 'number') {
    return [];
  }
  return staticRoomMaster10.filter((room) => room.floorNumber === floorNumber);
}

/**
 * Filters rooms by occupancy status (e.g., FULL, PARTIAL, VACANT, MAINTENANCE)
 * @param {string} status
 * @returns {Array<Object>} Filtered rooms
 */
function filterRoomsByStatus(status) {
  if (!status || typeof status !== 'string') {
    return [];
  }
  return staticRoomMaster10.filter((room) => room.occupancyStatus.toUpperCase() === status.trim().toUpperCase());
}

/**
 * Retrieves air-conditioned rooms
 * @param {boolean} [isAC=true]
 * @returns {Array<Object>} Filtered rooms
 */
function filterRoomsByAC(isAC = true) {
  return staticRoomMaster10.filter((room) => room.airConditioned === isAC);
}

/**
 * Calculates aggregate summary statistics for Dataset 10
 * @returns {Object} Room inventory stats
 */
function getDatasetStats() {
  const totalRooms = staticRoomMaster10.length;
  const totalCapacity = staticRoomMaster10.reduce((sum, r) => sum + r.maxCapacity, 0);
  const totalOccupied = staticRoomMaster10.reduce((sum, r) => sum + r.currentOccupancy, 0);
  const vacantBeds = totalCapacity - totalOccupied;
  const acCount = staticRoomMaster10.filter((r) => r.airConditioned).length;
  const attachedBathCount = staticRoomMaster10.filter((r) => r.attachedBathroom).length;
  const avgFee = Math.round(staticRoomMaster10.reduce((sum, r) => sum + r.baseFeePerSemesterINR, 0) / (totalRooms || 1));

  return {
    datasetId: 'staticRoomMaster10',
    totalRooms,
    totalCapacity,
    totalOccupied,
    vacantBeds,
    occupancyRatePercentage: Number(((totalOccupied / (totalCapacity || 1)) * 100).toFixed(2)),
    acCount,
    nonAcCount: totalRooms - acCount,
    attachedBathCount,
    averageSemesterFeeINR: avgFee,
    lastCalculated: new Date().toISOString()
  };
}

module.exports = {
  staticRoomMaster10,
  getAllRooms,
  findRoomById,
  filterRoomsByBlock,
  filterRoomsByFloor,
  filterRoomsByStatus,
  filterRoomsByAC,
  getDatasetStats
};
